## Python 示例

```python
def fibonacci(n):
    """生成斐波那契数列"""
    a, b = 0, 1
    result = []
    for _ in range(n):
        result.append(a)
        a, b = b, a + b
    return result

# 输出前10个斐波那契数
print(fibonacci(10))
```

## JavaScript 示例

```javascript
// 简单的倒计时函数
function countdown(seconds) {
    const interval = setInterval(() => {
        console.log(`剩余时间：${seconds}秒`);
        seconds--;
        if (seconds < 0) {
            clearInterval(interval);
            console.log('时间到！🚀');
        }
    }, 1000);
}

countdown(5);
```

